- FN:verify_loaded: Verify page loaded (lines 49-60)
- FN:login: Perform login action (lines 79-95)
"""

from playwright.sync_api import Page, expect
import re

class LoginPage:
    """FN:LoginPage - Page Object for Login Page."""

    def __init__(self, page: Page):
        """FN:__init__ - Initialize with Page instance."""
        self.page = page

    def navigate(self):
        """FN:navigate - Navigate to login page."""
        self.page.goto(f"{self.base_url}/login")

    def verify_loaded(self):
        """FN:verify_loaded - Verify page is loaded."""
        expect(self.page).to_have_title(
            re.compile(r"Login|Sign In", re.IGNORECASE)
        )
        expect(self.username_input).to_be_visible()
        expect(self.password_input).to_be_visible()
        expect(self.login_button).to_be_visible()

    @property
    def username_input(self):
        """FN:username_input - Returns username input locator."""
        return self.page.get_by_label("Username")

    @property
    def password_input(self):
        """FN:password_input - Returns password input locator."""
        return self.page.get_by_label("Password")

    @property
    def login_button(self):
        """FN:login_button - Returns login button locator."""
        return self.page.get_by_role("button", name="Sign In")

    def login(self, username: str, password: str):
        """FN:login - Perform login with credentials."""
        self.username_input.fill(username)
        self.password_input.fill(password)
        self.login_button.click()
